/* @lc app=leetcode id=949 lang=kotlin */ class Solution { fun largestTimeFromDigits(arr: IntArray): String = arr.indices.flatMap { a -> arr.indices.flatMap { b -> arr.indices.flatMap { c -> arr.indices.map { d -> listOf(a, b, c, d) } } } }.filter { it.distinct().size == 4 }.map { (a, b, c, d) -> (10 * arr[a] + arr[b]) * 100 + 10 * arr[c] + arr[d] }.filter { it / 100 < 24 && it % 100 < 60 }.maxOrNull()?.let { "%02d:%02d".format(it / 100, it % 100) } ?: "" }